<template><admin-layout><admin-review-panel><a class="review-link" :href="route('admin.merchant.payouts')">← {{ $t('Back') }}</a><h1>{{ $t('Payout details') }}</h1><dl class="review-grid"><div v-for="item in details" :key="item[0]"><dt>{{ $t(item[0]) }}</dt><dd>{{ item[1] || '—' }}</dd></div></dl><p class="review-notice">{{ $t('Approval does not send funds. Processing broadcasts a transfer. Completion requires a verified receipt.') }}</p><p class="review-notice">{{ $t('Manual merchant completion requires a verified receipt adapter; use the tracked processing flow.') }}</p><form v-if="actions.length" @submit.prevent="submit"><label>{{ $t('Action') }} <themed-select v-model="action" required><option value="">{{ $t('Select') }}</option><option v-for="a in actions" :value="a" :key="a">{{ $t(a) }}</option></themed-select></label><label>{{ $t('Reason') }}<textarea v-model="notes" required minlength="10" maxlength="500" /></label><label><input type="checkbox" v-model="confirmed" required /> {{ $t('I have checked the asset, network, destination and amount.') }}</label><p v-for="(message,key) in $page.props.errors" :key="key" role="alert">{{ message }}</p><button :disabled="busy || !confirmed || !action">{{ $t('Submit') }}</button></form></admin-review-panel></admin-layout></template>
<script>
import AdminLayout from '@/Layouts/AdminLayout';import AdminReviewPanel from '@/Components/AdminReviewPanel';import Pagination from '@/Jetstream/Pagination';
export default {components:{AdminLayout,AdminReviewPanel},props:{payout:Object},data(){return{action:'',notes:'',confirmed:false,busy:false}},computed:{actions(){return this.payout.status==='pending'?['approve','reject']:this.payout.status==='approved'&&!this.payout.txn_hash?['process']:this.payout.status==='failed'?['retry']:[]},details(){const r=this.payout;return[['ID',r.id],['Merchant',r.merchant&&r.merchant.business_name],['Status',this.$t(r.status)],['Amount',r.amount_crypto||r.amount],['USD',r.amount_usd],['Network',r.network_id],['Destination',r.destination_address||r.address],['Transaction hash',r.txn_hash],['Confirmations',r.confirmations],['Date',r.created_at],['Notes',r.admin_notes||r.notes||r.error_message]]}},methods:{submit(){if(this.busy||!this.actions.includes(this.action)||!this.confirmed)return;this.busy=true;this.$inertia.post(this.route('admin.merchant.payouts.'+this.action,this.payout.id),{notes:this.notes,reason:this.notes,send_immediately:false},{onSuccess:()=>{this.confirmed=false;this.action=''},onFinish:()=>{this.busy=false}})}}};
</script>
